from flask import Flask, request, jsonify
import sys

app = Flask(__name__)

def function1():
    # Function 1 implementation here
    pass

def function2():
    # Function 2 implementation here
    pass

@app.route('/')
def index():
    return ""Choose a function: /func1 or /func2""

@app.route('/func<function_name>')
def choose_function(function_name):
    globals().get(f'function_{function_name}')()
    return jsonify({""result"": ""Function executed successfully""})

if __name__ == ""__main__"":
    if len(sys.argv) > 1:
        func = sys.argv[1]
        if func in ['func1', 'func2']:
            app.run()
    else:
        print(""Please provide a function name as command line argument."")
```

