0,"Create a Python class that handles JSON objects. This class should feature a method to convert data into a JSON string and another method to instantiate a new object from a JSON string. The class must include a registry for factory functions, indexed by ID, used to generate instances of its subclasses. Implement functions for adding new factory functions to the registry and for creating an instance of a subclass using the associated factory function based on a given ID. Provide only the code, omit any introductory or concluding text.",94,,"['```python
import json
from abc import ABC, abstractmethod
from typing import Any, Dict, Type

class JSONable(ABC):
    @abstractmethod
    def to_dict(self) -> Dict[str, Any]:
        pass

class JSONHandler:
    __factory_registry: Dict[str, Type[JSONable]] = {}

    @staticmethod
    def register_factory(cls: Type[JSONable]):
        id_ = cls.__name__
        if id_ in JSONHandler.__factory_registry:
            raise ValueError(f""Factory for ID '{id_}' already exists."")
        JSONHandler.__factory_registry[id_] = cls

    @staticmethod
    def from_json(id_: str, json_str: str) -> JSONable:
        cls = JSONHandler.__factory_registry.get(id_)
        if not cls:
            raise KeyError(f""No factory registered for ID '{id_}'."")
        obj = cls.from_json(json_str)
        return obj

    @staticmethod
    def to_json(obj: JSONable) -> str:
        return json.dumps(obj.to_dict())

class MySubClass(JSONable):
    def __init__(self, value: int):
        self.value = value

    def to_dict(self) -> Dict[str, Any]:
        return {""type"": self.__class__.__name__, ""value"": self.value}

MySubClass.register_factory()
obj = MySubClass(42)
json_str = JSONHandler.to_json(obj)
new_obj = JSONHandler.from_json(""MySubClass"", json_str)
```']",80,[0],[],True,0,0,0,

