import threading
import hashlib

class ServiceManagerPython:
    def __init__(self, service_command, interval):
        self.service_command = service_command
        self.interval = interval
        self.task = None

    def start(self):
        self.task = threading.Thread(target=self.run)
        self.task.start()

    def run(self):
        while True:
            subprocess.call([self.service_command, 'start'])
            time.sleep(self.interval)

    def stop(self):
        subprocess.call([self.service_command, 'stop'])
        self.task = None
