db = SQLAlchemy(app)
migrate = Migrate(app, db)
login_manager = LoginManager()
login_manager.init_app(app)

class User(UserMixin):
    pass

class Book(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    title = db.Column(db.String(80), nullable=False)
    author = db.Column(db.String(80))
    status = db.Column(db.String(20))

@login_manager.user_loader
def load_user(user_id):
    return User.query.get(int(user_id))

@app.route('/api/register', methods=['POST'])
def register():
    # Implement user registration logic here

@app.route('/api/login', methods=['POST'])
def login():
    # Implement user login logic here

@app.route('/api/logout')
@login_required
def logout():
    logout_user()
    return {'message': 'Successfully logged out.'}

@app.route('/api/books', methods=['GET'])
@login_required
def get_books():
    books = Book.query.all()
    return jsonify([book.__dict__ for book in books])

@app.route('/api/books/<int:id>', methods=['PUT'])
@login_required
def update_book(id):
    # Implement logic to update book details here

@app.route('/api/books/<int:id>', methods=['DELETE'])
@login_required
def delete_book(id):
    # Implement logic to delete a book from the collection here

@app.route('/api/books', methods=['POST'])
@login_required
def add_book():
    data = request.get_json()
    new_book = Book(title=data['title'], author=data['author'], status='available')
    db.session.add(new_book)
    db.session.commit()
    return {'message': 'Successfully added book.'}

@app.route('/api/books/availability', methods=['GET'])
@login_required
def check_book_availability():
    books = Book.query.all()
    for book in books:
        response = requests.get(f'http://external-db-url/{book.id}')
        book.status = response.json()['status']
        db.session.commit()
    return jsonify([book.__dict__ for book in books])
