0,"Write a Python script that parses a CSV file, calculates the median value of the third column for each group defined by the first two columns, and outputs the results in a new CSV file with headers. The script should dynamically allocate memory for handling large files and include error handling for non-numeric values in the third column.",120,,"['```python
import csv
from statistics import median
from typing import Iterator

def safe_float(value):
    try:
        return float(value)
    except ValueError:
        raise ValueError(""Non-numeric value encountered."")

def grouped(iterable, keyfunc):
    groups = []
    current_key = None
    for item in iterable:
        key = keyfunc(item)
        if current_key != key:
            if current_key is not None:
                yield groups
                groups = []
            current_key = key
        groups.append(item)
    if groups:
        yield groups

def parse_csv(input_file, output_file):
    input_reader = csv.DictReader(open(input_file))
    output_writer = csv.writer(open(output_file, 'w'))
    output_writer.writerow([""Group"", ""Median""])

    for group in grouped(input_reader, key=lambda x: (x['Column1'], x['Column2'])):
        column3_values = [safe_float(value['Column3']) for value in group if safe_float(value['Column3']) is not None]
        median_value = median(column3_values)
        output_writer.writerow([group[0]['Column1'], group[0]['Column2'], median_value])

# Usage example:
parse_csv('input.csv', 'output.csv')
```']",0,[0],[],True,0,0,0,

