        self.max_value = max_seq_num

    def generate_random_float(self):
        return float(self.min_value + (self.max_value - self.min_value) * random.random())

    def generate_random_int(self):
        return int(self.generate_random_float())

    @staticmethod
    def extract_last_line_sequence_number(file_path, sequence_pattern=r""(\d+)$""):
        try:
            with open(file_path, 'r') as file:
                lines = file.readlines()
                sorted_lines = sorted(lines, key=lambda x: x.strip(), reverse=True)
                last_line = sorted_lines[-1]
                match = re.search(sequence_pattern, last_line)
                if match:
                    sequence_number = int(match.group(1))
                    return sequence_number
                else:
                    raise ValueError(""No sequence number found in the last line."")
        except FileNotFoundError:
            print(f""Error: File '{file_path}' not found."")
            return None
