import random
from typing import List

class GamePlayer:
    def __init__(self, player_id: int, score: int, experience_level: int):
        self.player_id = player_id
        self.score = score
        self.experience_level = experience_level

def generate_players(num_players: int) -> List[GamePlayer]:
    players = []
    for i in range(1, num_players + 1):
        score = random.randint(0, 1000)
        experience_level = random.randint(1, 5)
        player = GamePlayer(i, score, experience_level)
        players.append(player)
    return players

def calculate_ranking(player: GamePlayer) -> int:
    return player.score + (player.experience_level * 10)

def create_leaderboard(num_players: int) -> List[GamePlayer]:
    players_list = generate_players(num_players)
    leaderboard_sorted_by_ranking = sorted(players_list, key=calculate_ranking, reverse=True)
    return leaderboard_sorted_by_ranking
