import time, os, hashlib, paramiko
from getpass import getpass

def executeShellCommand(command):
    process = subprocess.Popen(command, stdout=subprocess.PIPE, stderr=subprocess.STDOUM, shell=True)
    output, error = process.communicate()

    if output:
        print(""Output:"", output.decode())
    if error:
        print(""Error:"", error.decode())

class ShellAndHasher:
    def __init__(self):
        self.sftp = paramiko.SFTPClient()

    def connect(self, host, username, password):
        transport = paramiko.Transport((host, 22))
        transport.connect(username=username, password=password)
        self.sftp = transport.open_sftp()

    def executeAndHashCommand(self, command):
        self.sftp.open_sftp()
        hashObj = hashlib.sha256()
        self.executeShellCommand(""echo -n "" + command + "" | sha256sum"")
        hashedData = self.sftp.recv(1024)
        hashObj.update(hashedData)
        return hashObj.hexdigest()

    def disconnect(self):
        self.sftp.close()
