def update_dicts(lst_dicts, target_key, delimiter=' ', update_values=False):
    for dict_ in lst_dicts:
        if target_key not in dict_:
            dict_[target_key] = '' if update_values else []
        elif isinstance(dict_[target_key], str) and not update_values:
            dict_[target_key] += delimiter
        elif update_values:
            dict_[target_key] += delimiter + str(next(iter(dict_[target_key])))
```

