 if it does not exist, the program should create one. Subsequently, the code should scan the temporary folder for large files, categorize them based on their size, and prompt the user to select which ones to permanently delete.",276,,"['```python
import os
import time
import shutil
import sys

class DiskSpaceOptimizer:
    def __init__(self, temp_folder, backup_dir='backup', threshold=30 * 24 * 60 * 60): # days in seconds
        self.temp_folder = temp_folder
        self.backup_dir = backup_dir
        self.threshold = threshold
        self.backup_directory_exists()

    def backup_directory_exists(self):
        if not os.path.exists(self.backup_dir):
            os.makedirs(self.backup_dir)

    def get_files_older_than(self, path, threshold):
        files_to_delete = []
        for root, dirs, files in os.walk(path):
            for file in files:
                file_path = os.path.join(root, file)
                if time.time() - os.path.getctime(file_path) > threshold:
                    files_to_delete.append((file, file_path))
        return files_to_delete

    def get_large_files(self):
        large_files = {}
        for root, dirs, files in os.walk(self.temp_folder):
            for file in files:
                file_path = os.path.join(root, file)
                if os.path.getsize(file_path) > 1024**3: # GB size filtering
                    file_size = str(os.path.getsize(file_path))[:-3] + 'GB'
                    if file_size not in large_files:
                        large_files[file_size] = [file, file_path]
                    else:
                        large_files[file_size].append((file, file_path))
        return large_files

    def delete_files(self, files_to_delete):
        for file, file_path in files_to_delete:
            try:
                os.remove(file_path)
                print(f'File {file} deleted successfully')
            except Exception as e:
                print(f'Error deleting file {file}: {e}')

    def main(self):
        files_to_delete = self.get_files_older_than(self.temp_folder, self.threshold)
        if files_to_delete:
            self.delete_files(files_to_delete)
        large_files = self.get_large_files()
        for size in sorted(large_files):
            print(f'Files larger than {size}:')
            for file, file_path in large_files[size]:
                print(f'\t{file}: {file_path}')
            choice = input('Enter y to delete or n to skip deletion: ')
            if choice.lower() == 'y':
                self.delete_files([(file, file_path) for file, file_path in large_files[size]])

if __name__ == ""__main__"":
    temp_folder = sys.argv[1]
    optimizer = DiskSpaceOptimizer(temp_folder)
    optimizer.main()
