import subprocess
import sys
import time
import hashlib
import paramiko

def executeShellCommand(command):
    try:
        result = subprocess.check_output(command, shell=True, stderr=subprocess.STDOUM)
        return result
    except Exception as e:
        print(f""Error executing command '{command}': {str(e)}"")
        return None

def executeShellCommandWithSSHAndHash(ssh, command):
    hasher = hashlib.sha256()
    try:
        result = ssh.exec_command(command)
        for line in iter(result.readline, b''):
            hasher.update(line)
        return (result.returncode, hasher.digest())
    except Exception as e:
        print(f""Error executing command '{command}': {str(e)}"")
        return (-1, None)
