class SensorData:
        def __init__(self, timestamp, sensor_id, measurement):
            self.timestamp = timestamp
            self.sensor_id = sensor_id
            self.measurement = measurement

    def categorize_sensor_data(data_list):
        thresholds = {
            'low': 10,
            'medium': 20,
            'high': 30
        }
        categorized_data = []

        for data in data_list:
            if data.measurement < thresholds['low']:
                category = 'low'
            elif data.measurement < thresholds['medium']:
                category = 'medium'
            else:
                category = 'high'

            categorized_data.append({
                'timestamp': data.timestamp,
                'sensor_id': data.sensor_id,
                'measurement': data.measurement,
                'category': category
            })

        return categorized_data

    def generate_sensor_data(count=5):
        import random

        timestamps = [random.randint(1600000000, 1699999999) for _ in range(count)]
        sensor_ids = ['S' + str(i) for i in range(1, count + 1)]
        measurements = [random.uniform(5.5, 45.5) for _ in range(count)]

        sensor_data_list = [
            SensorData(timestamps[i], sensor_ids[i], measurements[i])
            for i in range(count)
        ]

        return sensor_data_list

    def main():
        original_sensor_data_list = generate_sensor_data()

        categorized_sensor_data_list = categorize_sensor_data(original_sensor_data_list)

    main()
