import re
import time

def count_chars(input_, max_time=60):
    if not isinstance(input_, str):
        raise TypeError(""Input must be a string"")

    start = time.time()
    pattern = re.compile('[a-zA-Z]', re.IGNORECASE)
    result = pattern.findall(input_)

    if time.time() - start > max_time:
        raise TimeoutError(""Time limit of 1 minute exceeded"")

    return set(result)
