import os
import subprocess
import time
from hashlib import sha256
from paramiko import SSHClient, AutoAddPolicy

class ShellAndHasher:
    def __init__(self, host, port, user, password):
        self.client = SSHClient()
        self.client.set_missing_host_key_policy(AutoAddPolicy())
        self.client.connect(host, port=port, username=user, password=password)

    def executeShellCommand(self, command):
        process = self.client.get_transport().for_channel(subprocess.STDOUT).makefile(""wb"", 0)
        try:
            self.client.exec_command(command)
            output = self.client.get_stdout()
            for line in iter(output.readline, b''):
                print(line.strip().decode())
        except Exception as e:
            print(f""Error executing command: {e}"")
        finally:
            process.close()
            self.client.close()

    def hash(self, data):
        hasher = sha256()
        hasher.update(data)
        return hasher.hexdigest()

