```python
from profiles_generator import generate_profile

def generate_and_store_profiles():
    with open(""profiles.json"", ""w"") as f:
        data = []
        while len(data) < 100:
            data.append(generate_profile())
        json.dump(data, f)

if __name__ == ""__main__"":
    generate_and_store_profiles()
```

