2,"Create a function in Python that constructs a new linked list by extracting nodes from a given singly linked list, based on a specific value. The function should accept the head of the original linked list, the value to filter nodes by, and the index of the last node in the new list. The function should return a pointer to the head of the newly created linked list or None if there is insufficient memory. Additionally, it should update the 'next' attribute of the last node in the new list to point to None.",680,,"['```python
class Node:
    def __init__(self, data):
        self.data = data
        self.next = None

def filter_list(head, value, last_index):
    if head is None or last_index < 0:
        return None

    current = head
    new_head = None

    for _ in range(last_index + 1):
        if current is None or current.data == value:
            break

        if new_head is None:
            new_head = current
            current = current.next
        else:
            temp = current
            current = current.next
            temp.next = None

    if current is not None and current.data != value:
        if new_head is None:
            new_head = current
        else:
            temp = new_head
            while temp.next is not None:
                temp = temp.next
            temp.next = current
    return new_head
```']",50,[0],[],True,0,0,0,

