import time

def count_unique_alpha_chars(input_string):
    if not isinstance(input_string, str):
        raise ValueError(""Input must be a string"")

    allowed_chars = set('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ')
    unique_chars = set()

    start_time = time.time()

    for char in input_string:
        if char in allowed_chars:
            unique_chars.add(char.lower())

        if time.time() - start_time > 1:
            raise TimeoutError(""Function execution timed out"")

    return len(unique_chars)

def test_count_unique_alpha_chars():
    print(""Testing with valid input..."")
    assert count_unique_alpha_chars(""HelloWorld"") == 7, ""Failed on valid input 'HelloWorld'""

    print(""Testing with invalid input types..."")
    try:
        count_unique_alpha_chars(123)
        assert False, ""Failed to raise ValueError on non-string input""
    except ValueError as e:
        assert str(e) == ""Input must be a string"", ""Incorrect error message for non-string input""

    print(""Testing with large inputs and time constraints..."")
    try:
        count_unique_alpha_chars(""a"" * (10**6))  # Large string of 'a'
        assert False, ""Failed to raise TimeoutError on large input within 1 second""
    except TimeoutError as e:
        assert str(e) == ""Function execution timed out"", ""Incorrect error message for timeout""

test_count_unique_alpha_chars()
