import math
import time
import sys

def is_prime(n):
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    sqrt = int(math.sqrt(n))
    for i in range(3, sqrt + 1, 2):
        if n % i == 0:
            return False
    return True

def count_prime_factors(n):
    factors = set()
    while n > 1:
        if is_prime(n):
            factors.add(n)
            break
        else:
            for factor in range(2, int(math.sqrt(n)) + 1, 2):
                if n % factor == 0:
                    n //= factor
                    factors.add(factor)
                    break
    return len(factors)

def test_count_prime_factors():
    inputs = [2, 3, 4, 6, 7, 15, 20, 25, 49, 60, 81] + list(range(100, 1000001, 100))
    for input_num in inputs:
        start_time = time.time()
        result = count_prime_factors(input_num)
        if input_num < 2 or not isinstance(result, int):
            print(f""Test failed: expected a positive integer or none for {input_num}, got {result}"")
        elif result == 1 and input_num != 2 and input_num != 3:
            print(f""Test failed: expected 1 prime factor for {input_num}, got {result}"")
        if time.time() - start_time > 5:
            print(f""Test failed: timed out for {input_num}"")
    print(""All tests passed."")

def main():
    def validator(n):
        if not isinstance(n, int) or n <= 0:
            raise ValueError(""Input must be a positive integer"")
        return n

    count_prime_factors = lambda n: count_prime_factors(validator(n))

test_count_prime_factors()
```

