def build_http_request(url, method, headers=None, post_data=None, cookies=None, disable_ssl_verification=False):
    if method not in ['GET', 'POST']:
        raise ValueError(""Invalid HTTP method provided. Only GET and POST are supported."")

    request_string = f""{method.upper()} {url} HTTP/1.1\r\n""

    if headers is None:
        headers = {}

    if 'Host' not in headers:
        parsed_url = urlparse(url)
        headers['Host'] = parsed_url.netloc

    for key, value in headers.items():
        request_string += f""{key}: {value}\r\n""

