import hashlib
import time
from urllib.parse import unquote_to_bytes
import json

def validatePDUStruct(pdu):
    # Custom validation function to check the structure of NFAPI PDU
    # Replace this with your own logic based on the actual requirements
    if len(pdu) < 10 or len(pdu) % 4 != 0:
        return False
    return True

def hashFile(file_path, chunk_size=65536):
    md5 = hashlib.md5()
    with open(file_path, 'rb') as f:
        while True:
            data = f.read(chunk_size)
            if not data:
                break
            md5.update(data)
    return md5.hexdigest()

def generate_NFAPI_PDUs(N, data_len=4):
    PDUs = []
    for _ in range(N):
        pdu = b''
        for i in range(0, data_len * (len(_) + 1)):
            if i % data_len == 0:
                pdu += bytes([random.randint(0, 255)])
            else:
                pdu += b'\x00'
        PDUs.append(pdu)
    return [p for p in PDUs if validatePDUStruct(p)]

def main():
    N = 1000
    hashed_PDUs = []
    start_time = time.time()

    PDUs = generate_NFAPI_PDUs(N)
    for pdu in PDUs:
        pdu_hex = hex(int.from_bytes(pdu, byteorder='big')).replace('0x', '')
        hashed_Pdu = hashFile(pdu)
        print(f'Generated PDU: {len(pdu)} bytes -> Hex: {pdu_hex} | Hash: {hashed_Pdu}')
        hashed_PDUs.append((pdu, hashed_Pdu))
    print(f""Elapsed time: {time.time() - start_time} seconds"")

if __name__ == ""__main__"":
    main()
```

