0,"Create a Python function that constructs a new singly linked list by filtering nodes based on a specific value. The function should take the head of the original list, the filter value, and the index of the last node in the new list as inputs. It should return a pointer to the head of the new list or None if memory is insufficient. Update the 'next' attribute of the last node in the new list to point to None.",680,,"['```python
class Node:
    def __init__(self, data):
        self.data = data
        self.next = None

def filter_list(head, filter_value, last_index):
    if head is None:
        return None

    current = head
    new_head = None

    while current is not None and last_index >= 0:
        if current.data == filter_value:
            if new_head is None:
                new_head = current
            else:
                current_last = new_head
                while current_last.next is not None:
                    current_last = current_last.next
                current_last.next = current.next
        current = current.next
        last_index -= 1

    if last_index >= 0:
        current_last = new_head
        while current_last is not None:
            current_last = current_last.next
        current_last.next = None

    return new_head
