from hashlib import md5

def hexdigest(hash):
    return hash.hex()

def read_file(filename, chunksize=8192):
    with open(filename, 'rb') as f:
        while True:
            data = f.read(chunksize)
            if not data:
                break
            yield data

def hashFile(filename):
    hasher = md5()
    for chunk in read_file(filename, chunksize=8192):
        hasher.update(chunk)

    return hexdigest(hasher.digest())

