import hashlib
import sys

def hashFile(filename):
    file = open(filename, 'rb')
    md5 = hashlib.md5()
    block = file.read(8192)
    while len(block) > 0:
        md5.update(block)
        block = file.read(8192)
    return md5.hexdigest()

if __name__ == ""__main__"":
    if len(sys.argv) < 2:
        print(""Usage: python {0} filename"".format(sys.argv[0]))
    else:
        filename = sys.argv[1]
        hashResult = hashFile(filename)
        print(""MD5 Hash of {} is {}"".format(filename, hashResult))
