import hashlib
import os

def enhanced_file_md5_hash(file_path):
    md5 = hashlib.md5()
    with open(file_path, 'rb') as file:
        chunk = file.read(1024 * 1024)
        while chunk:
            md5.update(chunk)
            chunk = file.read(1024 * 1024)
    return md5.hexdigest()

directory_path = ""/path/to/directory""
