Here is a sample Python code for calculating SHA-256 hashes for notification entities:

```python
import hashlib
import struct
from ctypes import Structure, c_uint64, c_uint32, byref, cast

class Notification(Structure):
    _fields_ = [(""timestamp"", c_uint64), (""deviceId"", c_char_p), (""statusFlag"", c_uint32)]

def packNotification(notification):
    packed = struct.pack(""<Q32sI"", notification.timestamp, notification.deviceId, notification.statusFlag)
    return packed

def unpackNotification(data):
    return Notification(*struct.unpack_from(""<Q32sI"", data, 0))

def hashNotification(notification):
    packed = packNotification(notification)
    hasher = hashlib.sha256()
    hasher.update(packed)
    return hasher.digest()
```

