class Node:
    def __init__(self, data):
        self.data = data
        self.next = None

    def filter_list(head, filter_value, last_index):
        new_head = None
        current_node = None

        for _ in range(last_index + 1):
            current_node = Node(-1)
            if head is not None:
                head, current_node = current_node, head
            else:
                break

        while head is not None:
            if head.data != filter_value:
                if new_head is None:
                    new_head = head
                elif current_node.next is None:
                    current_node.next = head
                else:
                    current_node = current_node.next
            head = head.next

        while current_node is not None and current_node.data == -1:
            current_node = current_node.next
            if current_node is not None:
                current_node.data = None

        return new_head
