0,"Write a Python script that processes images based on command line arguments for color modes: grayscale, sepia, or black-white. Display usage instructions if no arguments are provided. Accepts an image file as input and applies the selected color mode, saving the processed image to a new file. Utilize Python Imaging Library (PIL) for image processing operations.",121,,"['```python
import sys
from PIL import Image

def process_image(input_file, mode):
    try:
        img = Image.open(input_file)
    except FileNotFoundError:
        print(""Error: The provided input file does not exist."")
        sys.exit()

    if mode == ""grayscale"":
        processed_img = img.convert(""L"")
    elif mode == ""sepia"":
        sepia_filter = ImageEnhance.Color(img)
        processed_img = sepia_filter.enhance(0.85)
    elif mode == ""black-white"":
        thresholded_img = Image.open(input_file).convert(""L"")
        inverted_img = thresholded_img.point(lambda p: 255 if p < 128 else 0)
        processed_img = inverted_img.convert(""RGB"")
    else:
        print(""Invalid color mode provided."")
        sys.exit()

    output_file = f""output_{mode}.png""
    processed_img.save(output_file)

def main():
    if len(sys.argv) < 3:
        print(""Usage: python script.py [image_file] [color_mode]"")
        sys.exit()

    input_file = sys.argv[1]
    mode = sys.argv[2]
    process_image(input_file, mode)

if __name__ == ""__main__"":
    main()
