import random

class AmplitudePhaseFrequency:
    def __init__(self, amplitude, phase, frequency):
        self.amplitude = amplitude
        self.phase = phase
        self.frequency = frequency

class LTE_Packet:
    def __init__(self, ue_index, tx_stream_id, dl_pdcp_sn):
        self.ue_index = ue_index
        self.tx_stream_id = tx_stream_id
        self.dl_pdcp_sn = dl_pdcp_sn

def create_lte_packet_array(num_packets):
    if num_packets <= 0:
        return []

    packets = [LTE_Packet(ue_index=rand_int(100), tx_stream_id=rand_int(5), dl_pdcp_sn=rand_int(256))
               for _ in range(num_packets)]

    amplitudes_phases_frequencies = [AmplitudePhaseFrequency(amplitude=rand_float(0.5),
                                                             phase=random_phase(),
                                                             frequency=random_frequency())
                                      for packet in packets]

    return packets, amplitudes_phases_frequencies

def rand_int(max_val):
    return random.randint(1, max_val)

def rand_float(max_val):
    return round(random.uniform(0.01 * max_val, max_val), 2)

def random_phase():
    # Considering a range of -pi to pi radians for phase randomness
    return round(random.uniform(-3.14159265358979323846, 3.14159265358979323846), 4)

def random_frequency():
    # Considering a range from 0 Hz to some maximum value based on context requirement
    return round(random.uniform(0, 10e6), 6)
