import logging
from functools import lru_cache
import sys

# Configure logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

@lru_cache(maxsize=128)
def get_db_connection():
    try:
        db = sqlite3.connect('products.db', timeout=5, isolation_level='READ COMMITTED')
        return db
    except SQLiteError as e:
        logger.error(f'Unable to connect to database: {e}')
        sys.exit(1)

def close_db_connection(conn):
    if conn:
        try:
            conn.close()
        except SQLiteError:
            logger.warning('Failed to close database connection')

def get_total_sales_by_category():
    with get_db_connection() as db:
        cursor = db.cursor()
        query = 'SELECT category, SUM(price) FROM sales GROUP BY category'
        cursor.execute(query)
        rows = cursor.fetchall()

        for row in rows:
            category, total_sales = row
            print(f'Total sales for category {category}: {total_sales}')

