Here is a simple implementation of the disk space optimization part in Python:

```python
import os
import shutil
import time
import glob
import hashlib
from paramiko import SSHClient, AutoAddPolicy, SFTPClient
import getpass

def optimize_disk(folder, backup_dir, age):
    if not os.path.exists(backup_dir):
        os.makedirs(backup_dir)

    files = glob.glob(f""{folder}/*"")
    for file in files:
        file_time = os.path.getctime(file)
        if time.time() - file_time > age:
            shutil.move(file, backup_dir)

def scan_large_files(folder):
    large_files = {}
    for foldername, subfolders, filenames in os.walk(folder):
        for filename in filenames:
            filepath = os.path.join(foldername, filename)
            if os.path.isfile(filepath):
                size = os.path.getsize(filepath)
                if size > 10485760:  # 10 MB
                    large_files[filepath] = size
    return large_files

