class TestIsOAuth2TokenValid(unittest.TestCase):
    def test_valid_token(self):
        data = '{""access_token"": ""test-token"", ""expires_in"": 3600, ""token_type"": ""Bearer"", ""issued_at"": ""2021-12-15T12:00:00Z""}'
        self.assertTrue(is_oauth2_token_valid(data, 'test-token', 3600, 'Bearer'))

    def test_missing_required_field(self):
        data = '{""access_token"": ""test-token"", ""expires_in"": 3600, ""token_type"": ""Bearer""}'
        self.assertFalse(is_oauth2_token_valid(data, 'test-token', 3600, 'Bearer', scope='test'))

    def test_invalid_expires_in(self):
        data = '{""access_token"": ""test-token"", ""expires_in"": -1, ""token_type"": ""Bearer""}'
        self.assertFalse(is_oauth2_token_valid(data, 'test-token', -1, 'Bearer'))

    def test_invalid_token_type(self):
        data = '{""access_token"": ""test-token"", ""expires_in"": 3600, ""token_type"": ""Invalid""}'
        self.assertFalse(is_oauth2_token_valid(data, 'test-token', 3600, 'Invalid'))

    def test_invalid_refresh_token(self):
        data = '{""access_token"": ""test-token"", ""expires_in"": 3600, ""token_type"": ""Bearer"", ""refresh_token"": ""not-valid""}'
