class ServiceManager:
    def __init__(self, start_command, stop_command):
        self.start_command = start_command
        self.stop_command = stop_command
        self.queue = queue.Queue()
        self.running = False
        self.thread = threading.Thread(target=self._run)

    def _run(self):
        try:
            self.running = True
            while self.running:
                # Run the service with interval delays between restarts
                run_service()
                time.sleep(5)
        except KeyboardInterrupt:
            print(""Service thread interrupted, stopping..."")
        finally:
            stop_service()
            self.running = False

    def start(self):
        if not self.running:
            self.thread.start()

    def stop(self):
        if self.running:
            self.queue.put(""Stop"")
