        self._service_status = False
        self._service_start_command = 'your-service-start-command'
        self._service_stop_command = 'your-service-stop-command'
        self._message_system_send_command = 'your-message-system-send-command'

    def start(self):
        self._service_status = True
        Popen(self._service_start_command)

    def stop(self):
        Popen(self._service_stop_command)
        time.sleep(5)  # delay for service to stop
        Popen(self._message_system_send_command)
        self._service_status = False

    def is_running(self):
        return self._service_status

def worker():
