import random

class Job:
    def __init__(self, job_title, estimated_duration, required_skills):
        self.job_title = job_title
        self.estimated_duration = estimated_duration
        self.required_skills = set(required_skills)

    def get_skill_count(self):
        return len(self.required_skills)

    def get_average_estimated_duration(jobs):
        total_hours = sum([job.estimated_duration for job in jobs])
        return total_hours / len(jobs)

    def generate_jobs(job_titles, durations, skills, num_jobs):
        if len(job_titles) < num_jobs:
            raise ValueError(""Not enough job titles provided."")
        if len(durations) < num_jobs:
            raise ValueError(""Not enough durations provided."")
        if len(skills) < 3*num_jobs:
            raise ValueError(""Not enough skills provided."")

        jobs = []
        for _ in range(num_jobs):
            job_title = random.choice(job_titles)
            estimated_duration = random.choices(durations)[0]
            required_skills = set(random.sample(skills, 3))
            jobs.append(Job(job_title, estimated_duration, list(required_skills)))
        return jobs
