```python
import json
from typing import Any, Callable, Dict

class EncryptableJSON:
    def __init__(self, data: Any):
        self.data = data
        self.id = None

    @staticmethod
    def register(id: str, factory: Callable[[Any], EncryptableJSON]):
        Registry[id] = factory

    @classmethod
    def from_json(cls, json_string: str, id: str = None):
        if id is not None and id in Registry:
            return Registry[id](json.loads(json_string))
        else:
            # Default behavior for unknown ID or no ID provided
            return cls.from_decrypted_json(json_string)

    @classmethod
    def to_json(cls, instance: EncryptableJSON) -> str:
        # Implement encryption here using the registered factory function's encryption capabilities
        return json.dumps(instance.data)

Registry: Dict[str, Callable[[Any], EncryptableJSON]] = {}
```

