= validateAndEncrypt",798,,"[' Here's the code for the given programming task:

```python
import json
import hashlib
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.backends import default_backend

class TokenData:
    def __init__(self, access_token, expiration_time, token_type):
        self.access_token = access_token
        self.expiration_time = expiration_time
        self.token_type = token_type

def parseToken(json_string):
    try:
        data = json.loads(json_string)
        return TokenData(data.get('access_token'), data.get('expiration_time'), data.get('token_type'))
    except json.JSONDecodeError:
        return None

def isValidToken(token_data):
    if not token_data or not token_data.access_token or token_data.expiration_time <= 0 or token_data.token_type != ""Bearer"":
        return False
    return True

def validateAndEncrypt(token_data):
    if not isValidToken(token_data):
        return False

    input_hash = hashlib.sha256(str(token_data.access_token) + str(token_data.expiration_time)).digest()
    custom_key = input_hash[:16]  # Using first 16 bytes as key for DES-CBC

    iv = hashlib.pbkdf2_hmac('sha256', custom_key, str(token_data.access_token) + str(token_data.expiration_time), 1000)[:8]

    backend = default_backend()
    cipher_algorithm = algorithms.TripleDES(custom_key)
    cipher_mode = modes.CBC(iv)

    cipher_context = Cipher(cipher_algorithm, cipher_mode, backend=backend)

    encryptor = cipher_context.encryptor()

    dummy_data_to_encrypt = b""dummy data for encryption""

    encrypted_dummy_data_padded = encryptor.update(dummy_data_to_encrypt) + encryptor.finalize()

    decryption_info_dict = {""key"": custom_key.hex(), ""iv"": iv.hex()}

    return (True, encrypted_dummy_data_padded, decryption_info_dict)
