3,"Write a Python function that takes a CSV file path as input and processes the data to calculate the average temperature for each month across all years in the dataset. The function should return a dictionary where the keys are the months (January, February, etc.) and the values are the average temperatures for each respective month. It should handle missing or invalid data by ignoring it and only calculating averages based on complete records. Additionally, provide an option to filter out temperatures above or below a certain threshold before calculating averages.",798,,"[""```python
import csv
from typing import Dict, List, Tuple

def process_csv(file_path: str, temperature_column: int, filter_threshold: float = None) -> Dict[str, float]:
    data = {}
    months = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December']

    with open(file_path, newline='') as csvfile:
        reader = csv.DictReader(csvfile)
        for row in reader:
            if not row[temperature_column].isnumeric() or float(row[temperature_column]) > filter_threshold or float(row[temperature_column]) < -filter_threshold:
                continue
            month = months[int(row['Month'])-1]
            if month in data:
                data[month].append(float(row[temperature_column]))
            else:
                data[month] = [float(row[temperature_column])]

    averages = {}
    for month, temperatures in data.items():
        if len(temperatures) > 0:
            averages[month] = sum(temperatures)/len(temperatures)

    return averages
